--[=[
    @class ITangSengDebugger
    唐僧调试器接口
]=]

export type ITangSengDebugger = {
    --- 是否弃用
    enable: boolean,

    --- 更多组件
    moreWidgets: {
        --- 玩家选择器，调用该ui将生成一个窗口，用来选择玩家
        --- 返回两个成员：
        --- - 第一个为选中的 userId 或者 nil
        --- - 第二个为清除当前选中的回调函数
        playerSelection: () -> (number?, () -> ())
    },

    --- 获取ui组件列表
    getWidgets: (self: ITangSengDebugger) -> (),

    --- 获取更多ui组件列表
    getMoreWidgets: (self: ITangSengDebugger) -> {
        playerSelection: (debugger: ITangSengDebugger) -> (() -> (number?, () -> ())),
        textBox: () -> ()
    },

    --- 获取Matter实例
    getMatter: (self: ITangSengDebugger) -> Matter,

    --- 获取组件列表
    getComponents: (self: ITangSengDebugger) -> { MatterComponent },

    --- 获取Plasma实例
    getPlasma: (self: ITangSengDebugger) -> Plasma,

    --- 获取 ecs world
    getWorld: (self: ITangSengDebugger) -> {},

    --- 开/关 Debugger 面板
    toggle: (self: ITangSengDebugger) -> ()
}

return {}
